export function drawHillshade(painter: Painter, tileManager: TileManager, layer: HillshadeStyleLayer, tileIDs: Array<OverscaledTileID>, renderOptions: RenderOptions) {
    if (painter.renderPass !== 'offscreen' && painter.renderPass !== 'translucent') return;

    const { isRenderingToTexture } = renderOptions;
    const context = painter.context;
    const projection = painter.style.projection;
    const useSubdivision = projection.useSubdivision;

    const depthMode = painter.getDepthModeForSublayer(0, DepthMode.ReadOnly);
    const colorMode = painter.colorModeForRenderPass();

    // Check if this is a shadow layer
    const isShadowLayer = layer.id.includes('shadow');

    if (painter.renderPass === 'offscreen') {
        // Prepare tiles
        prepareHillshade(painter, tileManager, tileIDs, layer, depthMode, StencilMode.disabled, colorMode);

        // Global Shadow Map Generation (Screen Space Mosaic)


        context.viewport.set([0, 0, painter.width, painter.height]);
    } else if (painter.renderPass === 'translucent') {
        // Globe (or any projection with subdivision) needs two-pass rendering to avoid artifacts when rendering texture tiles.
        // See comments in draw_raster.ts for more details.
        if (useSubdivision) {
            // Two-pass rendering
            const [stencilBorderless, stencilBorders, coords] = painter.stencilConfigForOverlapTwoPass(tileIDs);
            renderHillshade(painter, tileManager, layer, coords, stencilBorderless, depthMode, colorMode, false, isRenderingToTexture); // draw without borders
            renderHillshade(painter, tileManager, layer, coords, stencilBorders, depthMode, colorMode, true, isRenderingToTexture); // draw with borders
        } else {
            // Simple rendering
            const [stencil, coords] = painter.getStencilConfigForOverlapAndUpdateStencilID(tileIDs);
            renderHillshade(painter, tileManager, layer, coords, stencil, depthMode, colorMode, false, isRenderingToTexture);
        }
    }
}

function renderHillshade(
    painter: Painter,
    tileManager: TileManager,
    layer: HillshadeStyleLayer,
    coords: Array<OverscaledTileID>,
    stencilModes: { [_: number]: Readonly<StencilMode> },
    depthMode: Readonly<DepthMode>,
    colorMode: Readonly<ColorMode>,
    useBorder: boolean,
    isRenderingToTexture: boolean
) {
    const projection = painter.style.projection;
    const context = painter.context;
    const transform = painter.transform;
    const gl = context.gl;
    const EXTENT = 8192; // Standard extent

    const defines = [`#define NUM_ILLUMINATION_SOURCES ${layer.paint.get('hillshade-highlight-color').values.length}`];
    const program = painter.useProgram('hillshade', null, false, defines);
    const align = !painter.options.moving;

    const tilesByCanonical = new Map<string, Tile>();
    const debugMode = typeof window !== 'undefined' && (window as any)._shadowDebugMode;
    if (debugMode) {
        // console.log(">>> XPLORE-ENGINE-V4.15.44-CAPPED-GLOW-ACTIVE <<<");
    }

    // 1. Efficient Lazy Lookup Indexing
    const indexTile = (t: Tile) => {
        if (!t.dem || !t.dem.data) return;
        tilesByCanonical.set(t.tileID.key, t);
        tilesByCanonical.set(`${t.tileID.wrap}/${t.tileID.canonical.z}/${t.tileID.canonical.x}/${t.tileID.canonical.y}`, t);
    };

    // Fast index of current viewport and in-view tiles (usually < 50 items)
    const inViewTiles = (tileManager as any)._inViewTiles;
    if (inViewTiles && typeof inViewTiles.getAllTiles === 'function') {
        for (const t of inViewTiles.getAllTiles()) {
            indexTile(t);
        }
    }

    // Lazy neighbor finder
    const getNeighborTile = (id: OverscaledTileID) => {
        let neighbor = tilesByCanonical.get(id.key);
        if (!neighbor) {
            // Check cache specifically for this key
            const outOfViewCache = (tileManager as any)._outOfViewCache;
            if (outOfViewCache) {
                neighbor = outOfViewCache.getByKey(id.key);
            }
            if (neighbor && neighbor.dem && neighbor.dem.data) {
                indexTile(neighbor);
            }
        }
        return neighbor;
    };

    if (debugMode && coords.length > 0) {
        // Silent Diagnostic: Keep metadata alive for potential trace but remove noise
    }

    for (const coord of coords) {
        const tile = tileManager.getTile(coord);

        // Always use regular FBO for main texture (contains derivatives in RG)
        const fbo = tile.fbo;
        if (!fbo) {
            continue;
        }
        const mesh = projection.getMeshFromTileID(context, coord.canonical, useBorder, true, 'raster');

        const terrainData = painter.style.map.terrain?.getTerrainData(coord);

        // Bind regular FBO to texture unit 0 (for native hillshade/slope)
        // This contains PRE-CALCULATED SLOPE and ELEVATION
        context.activeTexture.set(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, fbo.colorAttachment.get());

        // Bind Raw DEM (High Precision) to Unit 1
        // We use Unit 1 because Unit 9 might be out of range on some implementations & 1-8 are now free (neighbors removed)
        context.activeTexture.set(gl.TEXTURE1);
        if (tile.demTexture) {
            tile.demTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
        } else if (painter.emptyTexture) {
            painter.emptyTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
        }

        // Bind Neighbor Textures for Extended Shadow Raymarching (Units 2-9)
        // CRITICAL: Order must match hillshade_program clockwise: N, NE, E, SE, S, SW, W, NW
        const neighborInfos: NeighborInfo[] = [
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, 0, -1),  // N (Unit 2)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, 1, -1),  // NE (Unit 3)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, 1, 0),   // E (Unit 4)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, 1, 1),   // SE (Unit 5)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, 0, 1),   // S (Unit 6)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, -1, 1),  // SW (Unit 7)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, -1, 0),  // W (Unit 8)
            getNeighborTileWithZoom(tileManager, tilesByCanonical, getNeighborTile, coord, -1, -1)  // NW (Unit 9)
        ];

        // Explicitly pull fresh uniform values for this tile
        const uniformValues = hillshadeUniformValues(painter, tile, layer);

        // Bind neighbor textures and pass zoom info
        for (let i = 0; i < 8; i++) {
            const n = neighborInfos[i];
            const t = n.tile;

            // V4.15.25: Use safer Unit offset starting at 4 to avoid internal collisions
            const unit = gl.TEXTURE4 + i;

            let tex: Texture | null = null;
            if (t) {
                tex = ensureDemTexture(painter, t);
            }

            context.activeTexture.set(unit);

            if (tex) {
                tex.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
            } else {
                // V4.15.21: SEAMLESS MIRROR FALLBACK 
                // If neighbor is MISS, bind the central tile as a surrogate.
                // We use zoomInfo = [0,0,0,0] as a sentinel to tell the shader to clamp/mirror.
                const centerTex = ensureDemTexture(painter, tile);
                if (centerTex) {
                    centerTex.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
                    neighborInfos[i].zoomInfo = [0.0, 0.0, 0.0, 0.0];
                } else if (painter.emptyTexture) {
                    painter.emptyTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
                }
            }
        }

        // Pass the actual neighbor zoom info to the shader using clockwise names
        // Note: Using explicit uniform assignment to ensure type safety and binding
        const uValues = uniformValues as any;
        uValues['u_neigh_zoom_n'] = neighborInfos[0].zoomInfo;
        uValues['u_neigh_zoom_ne'] = neighborInfos[1].zoomInfo;
        uValues['u_neigh_zoom_e'] = neighborInfos[2].zoomInfo;
        uValues['u_neigh_zoom_se'] = neighborInfos[3].zoomInfo;
        uValues['u_neigh_zoom_s'] = neighborInfos[4].zoomInfo;
        uValues['u_neigh_zoom_sw'] = neighborInfos[5].zoomInfo;
        uValues['u_neigh_zoom_w'] = neighborInfos[6].zoomInfo;
        uValues['u_neigh_zoom_nw'] = neighborInfos[7].zoomInfo;

        // Debug Logger (Enhanced)
        // V4.15.26: Console logging removed for performance and clarity.
        // Debugging is now handled visually via heatmap/sentinel diagnostics.

        const projectionData = transform.getProjectionData({
            overscaledTileID: coord,
            aligned: align,
            applyGlobeMatrix: !isRenderingToTexture,
            applyTerrainMatrix: true
        });

        program.draw(context, gl.TRIANGLES, depthMode, stencilModes[coord.overscaledZ], colorMode, CullFaceMode.backCCW,
            uniformValues, terrainData, projectionData, layer.id, mesh.vertexBuffer, mesh.indexBuffer, mesh.segments);
    }
}

// hillshade rendering is done in two steps. the prepare step first calculates the slope of the terrain in the x and y
// directions for each pixel, and saves those values to a framebuffer texture in the r and g channels.
function prepareHillshade(
    painter: Painter,
    tileManager: TileManager,
    tileIDs: Array<OverscaledTileID>,
    layer: HillshadeStyleLayer,
    depthMode: Readonly<DepthMode>,
    stencilMode: Readonly<StencilMode>,
    colorMode: Readonly<ColorMode>) {

    const context = painter.context;
    const gl = context.gl;

    for (const coord of tileIDs) {
        const tile = tileManager.getTile(coord);
        const dem = tile.dem;

        if (!dem || !dem.data) {
            continue;
        }

        // Cache unpack vector for Shadow Pass (since DEM might be unloaded later)
        if (dem) {
            (tile as any).cachedUnpackVector = dem.getUnpackVector();
            (tile as any).cachedDemStride = dem.stride;
        }

        if (!tile.needsHillshadePrepare) {
            continue;
        }

        const tileSize = dem.dim;
        const textureStride = dem.stride;

        const pixelData = dem.getPixels();
        context.activeTexture.set(gl.TEXTURE1);

        context.pixelStoreUnpackPremultiplyAlpha.set(false);
        tile.demTexture = tile.demTexture || painter.getTileTexture(textureStride);
        if (tile.demTexture) {
            const demTexture = tile.demTexture;
            demTexture.update(pixelData, { premultiply: false });
            demTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
        } else {
            tile.demTexture = new Texture(context, pixelData, gl.RGBA, { premultiply: false });
            tile.demTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);
        }

        context.activeTexture.set(gl.TEXTURE0);

        let fbo = tile.fbo;

        if (!fbo) {
            const renderTexture = new Texture(context, { width: tileSize, height: tileSize, data: null }, gl.RGBA);
            renderTexture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);

            fbo = tile.fbo = context.createFramebuffer(tileSize, tileSize, true, false);
            fbo.colorAttachment.set(renderTexture.texture);
        }

        context.bindFramebuffer.set(fbo.framebuffer);
        context.viewport.set([0, 0, tileSize, tileSize]);

        painter.useProgram('hillshadePrepare').draw(context, gl.TRIANGLES,
            depthMode, stencilMode, colorMode, CullFaceMode.disabled,
            hillshadeUniformPrepareValues(tile.tileID, dem),
            null, null, layer.id, painter.rasterBoundsBuffer,
            painter.quadTriangleIndexBuffer, painter.rasterBoundsSegments);

        tile.needsHillshadePrepare = false;
    }
}

// Helper to ensure GPU texture exists for a tile (handling neighbors)
// IMPORTANT: We must create fresh textures for neighbors because MapLibre recycles
// tile objects, and their demTexture might be stale (from previous lifecycle).
function ensureDemTexture(painter: Painter, tile: Tile) {
    const context = painter.context;

    // 1. If we already have a fresh texture, return it
    if (tile.demTexture && !tile.needsHillshadePrepare) {
        return tile.demTexture;
    }

    const dem = tile.dem;
    // V4.15.24: STRICT DATA CHECK. If dem or dem.data is missing, return NULL. 
    // This forces the engine to use Mirroring Fallback rather than a stale black texture.
    if (!dem || !dem.data) {
        return null;
    }

    const stride = dem.stride;
    tile.demTexture = tile.demTexture || painter.getTileTexture(stride);

    if (tile.demTexture) {
        const pixelData = dem.getPixels();
        tile.demTexture.update(pixelData, { premultiply: false });
        // Mark as fresh
        tile.needsHillshadePrepare = false;
    }

    return tile.demTexture;
}

// IMPORTANT: Returns tile and zoom scaling info for correct parent tile sampling
// Returns: { tile: Tile | null, zoomInfo: [scale, offsetX, offsetY, 0] }
interface NeighborInfo {
    tile: Tile | null;
    zoomInfo: [number, number, number, number]; // [scale, offsetX, offsetY, reserved]
}

function getNeighborTileWithZoom(tileManager: TileManager, tilesByCanonical: Map<string, Tile>, getNeighborTile: (id: any) => Tile | null, coord: OverscaledTileID, dx: number, dy: number): NeighborInfo {
    const z = coord.canonical.z;
    let wrappedX = coord.canonical.x + dx;
    let vy = coord.canonical.y + dy;
    let newWrap = coord.wrap;

    const tilesPerSide = (1 << z);
    if (wrappedX < 0) {
        wrappedX += tilesPerSide;
        newWrap--;
    } else if (wrappedX >= tilesPerSide) {
        wrappedX -= tilesPerSide;
        newWrap++;
    }

    // Check bounds Y
    if (vy < 0 || vy >= tilesPerSide) {
        return { tile: null, zoomInfo: [1.0, 0.0, 0.0, 0.0] };
    }

    let tile: Tile | null = null;
    let scanZ = z;

    // DEEP PARENTAL FALLBACK: Search up to 10 levels to find any available terrain data.
    // This virtually guarantees continental continuity if any low-zoom tiles are loaded.
    const minZ = Math.max(0, z - 10);

    while (scanZ >= minZ) {
        const nx = Math.floor(wrappedX / (1 << (z - scanZ)));
        const ny = Math.floor(vy / (1 << (z - scanZ)));
        const wrap = newWrap;
        const key1 = `${wrap}/${scanZ}/${nx}/${ny}`;
        const key2 = `${scanZ}/${nx}/${ny}`;
        const key3 = `os/${scanZ}/${wrap}/${nx}/${ny}`;

        // Comprehensive Multi-Path Lookup via Lazy getNeighborTile
        tile = tilesByCanonical.get(key1) ||
            tilesByCanonical.get(key2) ||
            tilesByCanonical.get(key3) ||
            getNeighborTile({ key: key1 } as any) ||
            getNeighborTile({ key: key2 } as any) ||
            getNeighborTile({ key: key3 } as any);

        if (tile) break;
        scanZ--;
    }

    if (!tile) {
        // V4.19.16: Removed on-the-fly tile addition during render.
        // This was causing infinite repaint cycles when neighbors were missing.
        // Neighbor pre-fetching should be handled by the SourceCache/TileManager.
        return { tile: null, zoomInfo: [1.0, 0.0, 0.0, 0.0] };
    }

    const tileZ = tile.tileID.canonical.z;
    const zoomDiff = z - tileZ;
    if (zoomDiff === 0) return { tile, zoomInfo: [1.0, 0.0, 0.0, 0.0] };

    const scale = 1.0 / (1 << zoomDiff);
    const divisor = 1 << zoomDiff;
    let offsetX = (wrappedX % divisor) / divisor;
    let offsetY = (vy % divisor) / divisor;

    return { tile, zoomInfo: [scale, offsetX, offsetY, 0.0] };
}
