import { mat4 } from 'gl-matrix';
import {
    Uniform1f,
    Uniform1i,
    Uniform4f,
    UniformMatrix4f
} from '../uniform_binding';
import type { Context } from '../../gl/context';
import type { UniformValues, UniformLocations } from '../uniform_binding';
import type { OverscaledTileID } from '../../tile/tile_id';
import type { DEMData } from '../../data/dem_data';
import { EXTENT } from '../../data/extent';

export type ShadowPrepareUniformsType = {
    'u_matrix': UniformMatrix4f;
    'u_dem_center': Uniform1i;
    'u_dem_n': Uniform1i;
    'u_dem_s': Uniform1i;
    'u_dem_e': Uniform1i;
    'u_dem_w': Uniform1i;
    'u_dem_ne': Uniform1i;
    'u_dem_nw': Uniform1i;
    'u_dem_se': Uniform1i;
    'u_dem_sw': Uniform1i;
    'u_has_n': Uniform1f;
    'u_has_s': Uniform1f;
    'u_has_e': Uniform1f;
    'u_has_w': Uniform1f;
    'u_has_ne': Uniform1f;
    'u_has_nw': Uniform1f;
    'u_has_se': Uniform1f;
    'u_has_sw': Uniform1f;
    'u_unpack': Uniform4f;
};

export const shadowPrepareUniforms = (context: Context, locations: UniformLocations): ShadowPrepareUniformsType => ({
    'u_matrix': new UniformMatrix4f(context, locations.u_matrix),
    'u_dem_center': new Uniform1i(context, locations.u_dem_center),
    'u_dem_n': new Uniform1i(context, locations.u_dem_n),
    'u_dem_s': new Uniform1i(context, locations.u_dem_s),
    'u_dem_e': new Uniform1i(context, locations.u_dem_e),
    'u_dem_w': new Uniform1i(context, locations.u_dem_w),
    'u_dem_ne': new Uniform1i(context, locations.u_dem_ne),
    'u_dem_nw': new Uniform1i(context, locations.u_dem_nw),
    'u_dem_se': new Uniform1i(context, locations.u_dem_se),
    'u_dem_sw': new Uniform1i(context, locations.u_dem_sw),
    'u_has_n': new Uniform1f(context, locations.u_has_n),
    'u_has_s': new Uniform1f(context, locations.u_has_s),
    'u_has_e': new Uniform1f(context, locations.u_has_e),
    'u_has_w': new Uniform1f(context, locations.u_has_w),
    'u_has_ne': new Uniform1f(context, locations.u_has_ne),
    'u_has_nw': new Uniform1f(context, locations.u_has_nw),
    'u_has_se': new Uniform1f(context, locations.u_has_se),
    'u_has_sw': new Uniform1f(context, locations.u_has_sw),
    'u_unpack': new Uniform4f(context, locations.u_unpack)
});

export type NeighborFlags = {
    n: boolean;
    s: boolean;
    e: boolean;
    w: boolean;
    ne: boolean;
    nw: boolean;
    se: boolean;
    sw: boolean;
};

export const shadowPrepareUniformValues = (
    unpackVector: number[],
    neighbors: NeighborFlags
): UniformValues<ShadowPrepareUniformsType> => {
    const matrix = mat4.create();
    mat4.ortho(matrix, 0, EXTENT, -EXTENT, 0, 0, 1);
    mat4.translate(matrix, matrix, [0, -EXTENT, 0]);

    return {
        'u_matrix': matrix,
        'u_dem_center': 0,
        'u_dem_n': 1,
        'u_dem_s': 2,
        'u_dem_e': 3,
        'u_dem_w': 4,
        'u_dem_ne': 5,
        'u_dem_nw': 6,
        'u_dem_se': 7,
        'u_dem_sw': 8,
        'u_has_n': neighbors.n ? 1.0 : 0.0,
        'u_has_s': neighbors.s ? 1.0 : 0.0,
        'u_has_e': neighbors.e ? 1.0 : 0.0,
        'u_has_w': neighbors.w ? 1.0 : 0.0,
        'u_has_ne': neighbors.ne ? 1.0 : 0.0,
        'u_has_nw': neighbors.nw ? 1.0 : 0.0,
        'u_has_se': neighbors.se ? 1.0 : 0.0,
        'u_has_sw': neighbors.sw ? 1.0 : 0.0,
        'u_unpack': unpackVector
    };
};

export {
    shadowPrepareUniforms as uniforms,
    shadowPrepareUniformValues as uniformValues
};
