import {
    Uniform1i,
    Uniform1f,
    Uniform2f,
} from '../uniform_binding';
import { MercatorCoordinate } from '../../geo/mercator_coordinate';

import type { Context } from '../../gl/context';
import type { UniformValues, UniformLocations } from '../uniform_binding';
import type { Tile } from '../../tile/tile';
import type { Painter } from '../painter';
import type { NormalmapStyleLayer } from '../../style/style_layer/normalmap_style_layer';
import type { OverscaledTileID } from '../../tile/tile_id';

export type NormalmapUniformsType = {
    'u_image': Uniform1i;
    'u_latrange': Uniform2f;
    'u_exaggeration': Uniform1f;
};

const normalmapUniforms = (context: Context, locations: UniformLocations): NormalmapUniformsType => ({
    'u_image': new Uniform1i(context, locations.u_image),
    'u_latrange': new Uniform2f(context, locations.u_latrange),
    'u_exaggeration': new Uniform1f(context, locations.u_exaggeration),
});

const normalmapUniformValues = (
    painter: Painter,
    tile: Tile,
    layer: NormalmapStyleLayer,
): UniformValues<NormalmapUniformsType> => {
    return {
        'u_image': 0,
        'u_latrange': getTileLatRange(painter, tile.tileID),
        // Use hillshade-exaggeration since normalmap reuses hillshade properties
        'u_exaggeration': layer.paint.get('hillshade-exaggeration'),
    };
};

function getTileLatRange(painter: Painter, tileID: OverscaledTileID) {
    // for scaling the magnitude of a points slope by its latitude
    const tilesAtZoom = Math.pow(2, tileID.canonical.z);
    const y = tileID.canonical.y;
    return [
        new MercatorCoordinate(0, y / tilesAtZoom).toLngLat().lat,
        new MercatorCoordinate(0, (y + 1) / tilesAtZoom).toLngLat().lat];
}

export {
    normalmapUniforms,
    normalmapUniformValues,
};
